import duckdb,os,json
con=duckdb.connect(os.environ["PFF_DB"],read_only=True)
print([c[0] for c in con.execute("describe pff_premium").fetchall()])
r=con.execute("select * from pff_premium where category='video_plays' limit 1").fetchone()
cols=[c[0] for c in con.execute("describe pff_premium").fetchall()]
row=dict(zip(cols,r))
for k,v in row.items():
    if isinstance(v,str) and v.strip().startswith(('{','[')):
        j=json.loads(v); 
        def walk(o,p=""):
            if isinstance(o,dict):
                for kk,vv in o.items(): walk(vv,p+"."+kk)
            elif isinstance(o,list) and o: walk(o[0],p+"[0]")
            else:
                if any(s in p.lower() for s in ('receiver','target','player','passer','carrier','id')): print(p, repr(o)[:60])
        walk(j,k)
    else: print(k, repr(v)[:60])
EOF

