def codex_reads(skill):
    """Codex sessions that READ <skill>/SKILL.md with a shell command. Every Codex session
    lists every skill's path in its roster, so a bare path match counts all of them.
    The (\\"|[^"]) branch lets the match cross JSON-escaped quotes around the path."""
    pat = re.compile(r'(sed -n|Get-Content|cat |head |nl )(\\"|[^"]){0,120}/'
                     + re.escape(skill) + r'/SKILL\.md')
    n = 0
    for f in glob.glob(f"{H}/.codex/sessions/**/*.jsonl", recursive=True):
        try:
            if any(pat.search(line) for line in open(f, encoding="utf-8", errors="ignore")):
                n += 1
        except Exception:
            pass
    return n

# Detail modes for the audit skill (2026-11-02); the default output stays key=value only.
if len(sys.argv) > 2 and sys.argv[1] == "--codex-reads":
    for s in sys.argv[2:]:
        print(f"{s}\t{codex_reads(s)}")
    sys.exit(0)

u = usage()
canon_names = owned(CANON)          # R8-01: owned roster = real directories
_no = name_only(canon_names)
if len(sys.argv) > 1 and sys.argv[1] == "--never-used":
    for s in sorted(canon_names - set(u), key=str.lower):
        print(f"{s}\t{'unknown' if _no is None else ('name-only' if s in _no else 'shown')}")
    sys.exit(0)

